import{_ as a,o as s,c as t,a3 as i}from"./chunks/framework.bvEHUNtb.js";const g=JSON.parse('{"title":"能量状态系统","description":"观察时令、生命与关系状态变化的传统模型。","frontmatter":{"title":"能量状态系统","description":"观察时令、生命与关系状态变化的传统模型。","layout":"page","pageClass":"dao-doc-page dao-directory-page traditional-wisdom-directory","aside":false,"outline":false},"headers":[],"relativePath":"topics/traditional-wisdom/energy/index.md","filePath":"topics/traditional-wisdom/energy/index.md","lastUpdated":1786982540000}'),r={name:"topics/traditional-wisdom/energy/index.md"};function n(d,e,o,p,c,l){return s(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="四、能量状态系统" tabindex="-1">四、能量状态系统 <a class="header-anchor" href="#四、能量状态系统" aria-label="Permalink to &quot;四、能量状态系统&quot;">​</a></h1><p>这里的“能量”指向状态与趋势，而非脱离语境的神秘化解释。它帮助我们观察生长、旺衰、节律与相互作用；这些模型都应回到具体的时间、位置和关系中理解。</p><p>三篇文章从不同分辨率切入同一问题：五行如何在时间和关系中呈现出状态变化，并如何进一步投射到声音秩序。</p><div class="energy-grid"><a href="/topics/traditional-wisdom/energy/twelve-life-stages" class="energy-card"><span class="energy-card__index">16</span><div><h2>十二长生</h2><p>以地支宫位为坐标，细看五行从生长、旺盛到衰退、归藏的十二种状态。</p><span class="energy-card__tag">地支 · 精细状态</span></div></a><a href="/topics/traditional-wisdom/energy/five-elements-prosperity" class="energy-card"><span class="energy-card__index">17</span><div><h2>五行旺相休囚死</h2><p>以季节为尺度，快速理解五行在旺、相、休、囚、死之间的相对关系。</p><span class="energy-card__tag">时令 · 五种状态</span></div></a><a href="/topics/traditional-wisdom/energy/five-tones-twelve-pitches" class="energy-card"><span class="energy-card__index">18</span><div><h2>五音十二律</h2><p>从宫商角徵羽到十二律吕，理解声音、节气与时间秩序如何形成一套可推演的结构。</p><span class="energy-card__tag">音律 · 时间秩序</span></div></a></div><p>相关内容将明确区分早期文献、后世术数表达与当代整理；涉及具体使用时，应把它们视为观察框架，而非脱离条件的结论。</p>',5)])])}const y=a(r,[["render",n]]);export{g as __pageData,y as default};
